What is the output of this program?

import java.util.*;
interface Listener {
    void onEvent(String e);
}
class Button {
    private List<Listener> listeners = new ArrayList<>();
    void addListener(Listener l) { listeners.add(l); }
    void click() {
        for (Listener l : listeners) l.onEvent("click");
    }
}
public class Main {
    public static void main(String[] args) {
        Button b = new Button();
        b.addListener(e -> System.out.println("A:" + e));
        b.click();
        b.addListener(e -> System.out.println("B:" + e));
        b.click();
    }
}

