import java.util.*;
public class Main {
    public static void main(String[] args) {
        Queue<String> events = new LinkedList<>();
        events.add("start");
        events.add("key");
        events.add("stop");
        events.add("key");
        int keys = 0;
        while (!events.isEmpty()) {
            String e = events.poll();
            if (e.equals("stop")) break;
            if (e.equals("key")) keys++;
        }
        System.out.println(keys + " " + events.size());
    }
}

