import java.util.*;
public class Main {
    public static void main(String[] args) {
        Map<String, Runnable> handlers = new HashMap<>();
        int[] total = {0};
        handlers.put("add", () -> total[0] += 5);
        handlers.put("double", () -> total[0] *= 2);
        String[] incoming = {"add", "double", "add", "unknown", "double"};
        for (String ev : incoming) {
            handlers.getOrDefault(ev, () -> {}).run();
        }
        System.out.println(total[0]);
    }
}

